diff --git a/src/main/java/org/jsoup/safety/Cleaner.java b/src/main/java/org/jsoup/safety/Cleaner.java
index 7e0eb28d..cc78c664 100644
--- a/src/main/java/org/jsoup/safety/Cleaner.java
+++ b/src/main/java/org/jsoup/safety/Cleaner.java
@@ -71,13 +71,95 @@ public class Cleaner {
      @return true if no tags or attributes need to be removed; false if they do
      */
     public boolean isValid(Document dirtyDocument) {
+        return isValid(dirtyDocument, null);
+    }
+
+    /**
+     Determines if the input document <b>body</b>is valid, against the whitelist. It is considered valid if all the tags and attributes
+     in the input HTML are allowed by the whitelist, and that there is no content in the <code>head</code>.
+     <p>
+     This method can be used as a validator for user input. An invalid document will still be cleaned successfully
+     using the {@link #clean(Document)} document. If using as a validator, it is recommended to still clean the document
+     to ensure enforced attributes are set correctly, and that the output is tidied.
+     </p>
+     @param dirtyDocument document to test
+     @param originalHtml the original HTML string before parsing (for body fragment validation)
+     @return true if no tags or attributes need to be removed; false if they do
+     */
+    public boolean isValid(Document dirtyDocument, String originalHtml) {
         Validate.notNull(dirtyDocument);

+        // If original HTML is provided, check if it contains document structure tags
+        if (originalHtml != null) {
+            String lower = originalHtml.toLowerCase();
+            if (lower.contains("<html") || lower.contains("<head") || lower.contains("<body")) {
+                return false;
+            }
+
+            // Check for mismatched tags (unclosed or unmatched closing tags)
+            if (!isBalancedHtml(originalHtml)) {
+                return false;
+            }
+        }
+
+        // Check that head is empty (body HTML should not have head content)
+        Element head = dirtyDocument.head();
+        if (head != null && head.childNodeSize() > 0) {
+            return false;
+        }
+
         Document clean = Document.createShell(dirtyDocument.baseUri());
         int numDiscarded = copySafeNodes(dirtyDocument.body(), clean.body());
         return numDiscarded == 0;
     }

+    private boolean isBalancedHtml(String html) {
+        java.util.Stack<String> stack = new java.util.Stack<String>();
+        int i = 0;
+        while (i < html.length()) {
+            if (html.charAt(i) == '<') {
+                int endTag = html.indexOf('>', i);
+                if (endTag == -1) break;
+
+                String tag = html.substring(i + 1, endTag).trim();
+                if (tag.length() > 0) {
+                    if (tag.startsWith("/")) {
+                        // Closing tag
+                        String tagName = extractTagName(tag.substring(1));
+                        if (stack.isEmpty() || !stack.peek().equals(tagName)) {
+                            return false;
+                        }
+                        stack.pop();
+                    } else if (!tag.endsWith("/") && !isVoidElement(tag)) {
+                        // Opening tag (not self-closing and not void element)
+                        String tagName = extractTagName(tag);
+                        stack.push(tagName);
+                    }
+                }
+                i = endTag + 1;
+            } else {
+                i++;
+            }
+        }
+        return stack.isEmpty();
+    }
+
+    private String extractTagName(String tagStr) {
+        int space = tagStr.indexOf(' ');
+        if (space > 0) {
+            return tagStr.substring(0, space).toLowerCase();
+        }
+        return tagStr.toLowerCase();
+    }
+
+    private boolean isVoidElement(String tag) {
+        String tagName = extractTagName(tag).toLowerCase();
+        return tagName.equals("br") || tagName.equals("hr") || tagName.equals("img") ||
+               tagName.equals("input") || tagName.equals("meta") || tagName.equals("link") ||
+               tagName.equals("area") || tagName.equals("col") || tagName.equals("embed") ||
+               tagName.equals("source") || tagName.equals("track") || tagName.equals("wbr");
+    }
+

     /**
      Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
